INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P18','Health & Nutrition','Physical','Leaf','Application','6-8',false,'Health & Fitness Knowledge','Student identifies food groups and balanced meals, explains how nutrition fuels activity, and evaluates everyday food choices.','Student identifies food groups and balanced meals, explains how nutrition fuels activity, and evaluates everyday food choices.','["Student identifies food groups and balanced meals, explains how nutrition fuels activity, and evaluates everyday food choices."]'::jsonb,'{"x":1690,"y":1070,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Health & Nutrition','Physical','existing')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P19','Injury Prevention','Physical','Leaf','Integration','6-8',false,'Health & Fitness Knowledge','Student explains how to prevent common activity injuries, applies RICE for minor injuries, and recognizes when to stop and get adult help.','Student explains how to prevent common activity injuries, applies RICE for minor injuries, and recognizes when to stop and get adult help.','["Student explains how to prevent common activity injuries, applies RICE for minor injuries, and recognizes when to stop and get adult help."]'::jsonb,'{"x":1450,"y":550,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Injury Prevention','Physical','existing')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P10','Game Strategy','Physical','Leaf','Integration','6-8',false,'Health & Fitness Knowledge','Student explains offensive and defensive concepts such as creating space, defending space, and transitions, and chooses sound tactics in game scenarios.','Student explains offensive and defensive concepts such as creating space, defending space, and transitions, and chooses sound tactics in game scenarios.','["Student explains offensive and defensive concepts such as creating space, defending space, and transitions, and chooses sound tactics in game scenarios."]'::jsonb,'{"x":1020,"y":600,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Game Strategy','Physical','existing')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P8','Fitness Routines','Physical','Spine','Application','3-5',true,'Health & Fitness Knowledge','Student sequences a warm-up, main activity, and cool-down, and explains what each phase does for the body.','Student sequences a warm-up, main activity, and cool-down, and explains what each phase does for the body.','["Student sequences a warm-up, main activity, and cool-down, and explains what each phase does for the body."]'::jsonb,'{"x":1200,"y":1040,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Fitness Routines','Physical','existing')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P12','Performance Training','Physical','Spine','Integration','9-10',true,'Health & Fitness Knowledge','Student applies the FITT principle and progressive overload to design training that improves a chosen fitness component safely.','Student applies the FITT principle and progressive overload to design training that improves a chosen fitness component safely.','["Student applies the FITT principle and progressive overload to design training that improves a chosen fitness component safely."]'::jsonb,'{"x":1260,"y":600,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Performance Training','Physical','existing')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P-337','Fitness Goal Setting','Physical','Spine','Integration','6-8',true,'Health & Fitness Knowledge','Student writes SMART fitness goals, tracks progress against a baseline, and adjusts goals based on results.','Student writes SMART fitness goals, tracks progress against a baseline, and adjusts goals based on results.','["Student writes SMART fitness goals, tracks progress against a baseline, and adjusts goals based on results."]'::jsonb,'{"x":948,"y":2080,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Fitness Goal Setting','Physical','new')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P14','Personal Fitness Planning','Physical','Spine','Mastery','9-10',true,'Health & Fitness Knowledge','Student passes the planning quiz and submits a personal fitness plan with SMART goals, a weekly schedule covering all fitness components, and a reflection, approved by the teacher.','Student passes the planning quiz and submits a personal fitness plan with SMART goals, a weekly schedule covering all fitness components, and a reflection, approved by the teacher.','["Student passes the planning quiz and submits a personal fitness plan with SMART goals, a weekly schedule covering all fitness components, and a reflection, approved by the teacher."]'::jsonb,'{"x":1200,"y":250,"z_group":1,"color_cluster":"Health & Fitness Knowledge"}'::jsonb,'Personal Fitness Planning','Physical','existing')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P-340','Daily Activity Log','Physical','Spine','Fluency','3-5',true,'Active Habits','Student logs at least 30 minutes of physical activity on 20 different days, building a consistent movement habit.','Student logs at least 30 minutes of physical activity on 20 different days, building a consistent movement habit.','["Student logs at least 30 minutes of physical activity on 20 different days, building a consistent movement habit."]'::jsonb,'{"x":1026,"y":1940,"z_group":1,"color_cluster":"Active Habits"}'::jsonb,'Daily Activity Log','Physical','new')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P-341','Weekly Workout Habit','Physical','Leaf','Application','6-8',false,'Active Habits','Student completes and logs three structured workouts per week for four weeks (12 sessions).','Student completes and logs three structured workouts per week for four weeks (12 sessions).','["Student completes and logs three structured workouts per week for four weeks (12 sessions)."]'::jsonb,'{"x":1060,"y":1630,"z_group":1,"color_cluster":"Active Habits"}'::jsonb,'Weekly Workout Habit','Physical','new')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P-342','Stretching Routine','Physical','Leaf','Fluency','3-5',false,'Active Habits','Student completes and logs ten stretching or mobility sessions of at least 10 minutes.','Student completes and logs ten stretching or mobility sessions of at least 10 minutes.','["Student completes and logs ten stretching or mobility sessions of at least 10 minutes."]'::jsonb,'{"x":1110,"y":2100,"z_group":1,"color_cluster":"Active Habits"}'::jsonb,'Stretching Routine','Physical','new')
INSERT INTO curriculum_nodes (id,title,domain,path_type,stage,grade_band,primary_path,cluster,description,demonstration,mastery_criteria,visual,legacy_name,legacy_subject,source) VALUES ('P15','Physical Mastery','Physical','Leaf','Mastery','11-12',false,'Active Habits','Student has earned Advanced Conditioning, an approved Personal Fitness Plan, and mastery of at least one sport rubric — the capstone of the Physical path.','Student has earned Advanced Conditioning, an approved Personal Fitness Plan, and mastery of at least one sport rubric — the capstone of the Physical path.','["Student has earned Advanced Conditioning, an approved Personal Fitness Plan, and mastery of at least one sport rubric — the capstone of the Physical path."]'::jsonb,'{"x":1200,"y":220,"z_group":1,"color_cluster":"Active Habits"}'::jsonb,'Physical Mastery','Physical','existing')
